// Some portions generated by Codex
package org.eclipse.rdf4j.common.net;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.net.URISyntaxException;

import org.junit.jupiter.api.Test;

/**
 * Scanner compatibility contracts, including legacy acceptance that is intentionally not stricter RFC validation. The
 * expected components and UTF-16 error offsets are fixed values, not results obtained from another parser path.
 */
class ParsedIRIScannerCompatibilityTest {

	private static final String SUPPLEMENTARY = "\uD83D\uDE00";

	@Test
	void supplementaryCharactersPreserveEveryStringComponent() throws URISyntaxException {
		String input = "http://u" + SUPPLEMENTARY + ":p@h" + SUPPLEMENTARY + ".test:81/a" + SUPPLEMENTARY
				+ "?b" + SUPPLEMENTARY + "#c" + SUPPLEMENTARY;
		ParsedIRI iri = new ParsedIRI(input);

		assertComponents(iri, "http", "u" + SUPPLEMENTARY + ":p", "h" + SUPPLEMENTARY + ".test", 81,
				"/a" + SUPPLEMENTARY, "b" + SUPPLEMENTARY, "c" + SUPPLEMENTARY);
		assertTrue(iri.isAbsolute());
		assertFalse(iri.isOpaque());
		assertEquals(input, iri.toString());
		assertEquals(input.hashCode(), iri.hashCode());
		assertTrue(iri.equals(iri));
		assertFalse(iri.equals(null));
		assertFalse(iri.equals(input));
	}

	@Test
	void emptyAndUndefinedComponentsRemainDistinct() throws URISyntaxException {
		assertComponents(new ParsedIRI(""), null, null, null, -1, "", null, null);
		assertComponents(new ParsedIRI("//"), null, null, "", -1, "", null, null);
		assertComponents(new ParsedIRI("//@?#"), null, "", "", -1, "", "", "");
		assertComponents(new ParsedIRI("http://h:"), "http", null, "h", -1, "", null, null);
		assertComponents(new ParsedIRI("urn:opaque"), "urn", null, null, -1, "opaque", null, null);
		assertTrue(new ParsedIRI("urn:opaque").isOpaque());
		assertFalse(new ParsedIRI("").isAbsolute());
	}

	@Test
	void supplementaryCodePointBeforeEofOrDelimiterConsumesBothCodeUnits() throws URISyntaxException {
		assertComponents(new ParsedIRI("/" + SUPPLEMENTARY), null, null, null, -1, "/" + SUPPLEMENTARY,
				null, null);
		assertComponents(new ParsedIRI("/" + SUPPLEMENTARY + "?#"), null, null, null, -1,
				"/" + SUPPLEMENTARY, "", "");
		assertEquals("/%F0%9F%98%80", new ParsedIRI("/" + SUPPLEMENTARY).toASCIIString());
		assertEquals("/" + SUPPLEMENTARY, new ParsedIRI("/" + SUPPLEMENTARY).normalize().toString());
	}

	@Test
	void supplementaryCodePointsDoNotChangeUtf16ErrorOffsets() {
		assertSyntax("/a" + SUPPLEMENTARY + "%", "Illegal percent encoding U+25", 4);
		assertSyntax("/" + SUPPLEMENTARY + " ", "Unexpected character U+20", 3);
		assertSyntax("/" + SUPPLEMENTARY + "%0", "Illegal percent encoding U+25", 3);
		assertSyntax("/" + SUPPLEMENTARY + "%0G", "Illegal percent encoding U+25", 3);
		assertSyntax("http://[" + SUPPLEMENTARY, "Invalid host IP address", 10);
	}

	@Test
	void unpairedReversedAndInterruptedSurrogatesFailAtTheirFirstCodeUnit() {
		assertSyntax("/\uD800", "Unexpected character U+D800", 1);
		assertSyntax("/\uDC00", "Unexpected character U+DC00", 1);
		assertSyntax("/\uDC00\uD800", "Unexpected character U+DC00", 1);
		assertSyntax("/\uD800x\uDC00", "Unexpected character U+D800", 1);
		assertSyntax("/\uD800/\uDC00", "Unexpected character U+D800", 1);
		assertSyntax("/" + SUPPLEMENTARY + "\uD800", "Unexpected character U+D800", 3);
	}

	@Test
	void nulIsNotSilentlyAcceptedAsEndOfInput() {
		assertSyntax("\u0000", "Unexpected character U+0", 0);
		assertSyntax("/a\u0000b", "Unexpected character U+0", 2);
		assertSyntax("/" + SUPPLEMENTARY + "\u0000", "Unexpected character U+0", 3);
		assertSyntax("/p?q\u0000#f", "Unexpected character U+0", 4);
	}

	@Test
	void privateCharactersAreAllowedOnlyInQuery() throws URISyntaxException {
		String privateCharacters = "\uE000\uDB80\uDC00\uDBFF\uDFFD";
		assertEquals(privateCharacters, new ParsedIRI("?" + privateCharacters).getQuery());
		assertSyntax("/\uE000", "Unexpected character U+E000", 1);
		assertSyntax("#\uDB80\uDC00", "Unexpected character U+F0000", 1);
		assertSyntax("/\uD83F\uDFFE", "Unexpected character U+1FFFE", 1);
		assertSyntax("/\uFFFE", "Unexpected character U+FFFE", 1);
		assertEquals("/\uD7FF\uF900\uD83F\uDFFD", new ParsedIRI("/\uD7FF\uF900\uD83F\uDFFD").getPath());
	}

	@Test
	void schemeAndUserInfoRewindsPreserveSupplementaryCharacters() throws URISyntaxException {
		String relative = "abc" + SUPPLEMENTARY + ":tail";
		ParsedIRI withoutScheme = new ParsedIRI(relative);
		assertNull(withoutScheme.getScheme());
		assertEquals(relative, withoutScheme.getPath());
		assertComponents(new ParsedIRI("http://h" + SUPPLEMENTARY + "/p@q"), "http", null,
				"h" + SUPPLEMENTARY, -1, "/p@q", null, null);
		assertComponents(new ParsedIRI("http://h?q=@x"), "http", null, "h", -1, "", "q=@x", null);
	}

	@Test
	void ipLiteralMemberScannerPreservesLegacyUnicodeAcceptance() throws URISyntaxException {
		ParsedIRI iri = new ParsedIRI("http://[" + SUPPLEMENTARY + "]/p");
		assertEquals("[" + SUPPLEMENTARY + "]", iri.getHost());
		assertEquals("/p", iri.getPath());
		assertEquals("[]", new ParsedIRI("http://[]/").getHost());
	}

	@Test
	void numericHostsAndPortsPreserveLegacyValidation() throws URISyntaxException {
		assertEquals("1.example", new ParsedIRI("http://1.example/").getHost());
		assertEquals("385.fwk19480900", new ParsedIRI("bundle://385.fwk19480900/a").getHost());
		assertSyntax("http://127.0.0.256/", "Invalid IPv4 address U+2F", 18);
		assertEquals(65536, new ParsedIRI("http://h:65536/").getPort());
		assertEquals(Integer.MAX_VALUE, new ParsedIRI("http://h:2147483647/").getPort());
		NumberFormatException overflow = assertThrows(NumberFormatException.class,
				() -> new ParsedIRI("http://h:2147483648/"));
		assertEquals("For input string: \"2147483648\"", overflow.getMessage());
	}

	private static void assertComponents(ParsedIRI iri, String scheme, String userInfo, String host, int port,
			String path, String query, String fragment) {
		assertEquals(scheme, iri.getScheme());
		assertEquals(userInfo, iri.getUserInfo());
		assertEquals(host, iri.getHost());
		assertEquals(port, iri.getPort());
		assertEquals(path, iri.getPath());
		assertEquals(query, iri.getQuery());
		assertEquals(fragment, iri.getFragment());
	}

	private static void assertSyntax(String input, String reason, int index) {
		URISyntaxException error = assertThrows(URISyntaxException.class, () -> new ParsedIRI(input));
		assertEquals(URISyntaxException.class, error.getClass());
		assertEquals(input, error.getInput());
		assertEquals(reason, error.getReason());
		assertEquals(index, error.getIndex());
		assertEquals(reason + " at index " + index + ": " + input, error.getMessage());
	}
}
